// แปลง database เป็น Map เพื่อดึงชื่อได้ง่าย
var nameMap = {};
database.forEach(d => {
    nameMap[d.uuid] = d.nameuser;
});

var offlineDevices = [];
var onlineDevices = [];

var timeNow = Date.now();
var offLine = 20 * 60 * 1000; // 20 นาที

// ตรวจสอบสถานะอุปกรณ์
for (let i = 0; i < database.length; i++) {
    let device = database[i];
    let uid = device.uuid;
    let contextKey = 'uidmarqM5' + uid + ".timestamp";
    let lastTimeRaw = flow.get(contextKey);

    if (lastTimeRaw === undefined) {
        // node.warn(`Timestamp not found for ${uid} (context key: ${contextKey})`);
        offlineDevices.push({
            project: 'MARQ',
            uid: uid,
            status: 'M5 OFFLINE (no timestamp)',
            name: nameMap[uid] || 'UNKNOWN'
        });
        continue;
    }

    let lastTime = Number(lastTimeRaw);
    if (isNaN(lastTime)) {
        node.warn(`Invalid timestamp value for ${uid}: ${lastTimeRaw}`);
        offlineDevices.push({
            project: 'MARQ',
            uid: uid,
            status: 'M5 OFFLINE (invalid timestamp)',
            name: nameMap[uid] || 'UNKNOWN'
        });
        continue;
    }

    if (timeNow - lastTime <= offLine) {
        onlineDevices.push({
            project: 'MARQ',
            uid: uid,
            status: 'M5 ONLINE',
            name: nameMap[uid] || 'UNKNOWN'
        });
    } else {
        offlineDevices.push({
            project: 'MARQ',
            uid: uid,
            status: 'M5 OFFLINE',
            name: nameMap[uid] || 'UNKNOWN'
        });
    }
}

// node.warn("DEBUG START");
// node.warn("OFFLINE COUNT: " + offlineDevices.length);
// node.warn("ONLINE COUNT: " + onlineDevices.length);
// node.warn("CHANNEL MAP: " + JSON.stringify(channelMap));

for (let channelId in channelMap) {
    node.warn("Processing channelId: " + channelId);

    let devicesInChannel = channelMap[channelId];
    let uids = devicesInChannel.map(d => d.uuid);

    let offlineInChannel = offlineDevices.filter(d => uids.includes(d.uid));
    let onlineInChannel = onlineDevices.filter(d => uids.includes(d.uid));

    node.warn(`Channel ${channelId}: ${offlineInChannel.length} offline, ${onlineInChannel.length} online`);

    let notificationMessage = "";

    if (offlineInChannel.length > 0) {
        notificationMessage += "**⚠️ OFFLINE DEVICES!!**\n";
        offlineInChannel.forEach(d => {
            notificationMessage += `📡 PROJECT: ${d.project}\n🆔 UID: ${d.uid}\n❌ STATUS: ${d.status}\n👤 NAME: ${d.name}\n\n`;
        });
    }

    if (notificationMessage.length > 0) {
        // node.warn("Sending to Discord channel: " + channelId);
        // node.warn("Message: \n" + notificationMessage);

        node.send({
            payload: notificationMessage,
            channel: channelId
        });
    }
}
return null;

